{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "employees",
      "as": "with_band",
      "column": "band",
      "expr": "'senior' if salary >= 140000 else ('mid' if salary >= 100000 else 'junior')"
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "students",
      "as": "students_with_total",
      "column": "total",
      "expr": "null if is_null(math) or is_null(science) or is_null(english) else math + science + english"
    }
  ]
}

{
  "status": "plan",
  "steps": [
    {
      "op": "filter",
      "input": "students",
      "as": "filtered",
      "where": "not is_null(math) and not is_null(science) and not is_null(english)"
    },
    {
      "op": "derive",
      "input": "filtered",
      "as": "with_total",
      "column": "total",
      "expr": "math + science + english"
    },
    {
      "op": "select",
      "input": "with_total",
      "as": "selected",
      "columns": ["name", "total"]
    },
    {
      "op": "sort",
      "input": "selected",
      "as": "output",
      "by": [
        {
          "column": "total",
          "order": "desc"
        }
      ]
    }
  ]
}

